<!-- 我的职务 -->
<template>
	<view class="page">
		<view class="single-line-box" style="">
			
			<input 
				class="nickname-input"
				type="text" 
				:value="position" 
				:model="position" 
				placeholder="请填入职务~"
				maxlength="12"
				@input="typingContent"/>
			
			<view class="counts-limt" style="margin-top: 10px;">
				<text class="tips">*注：填写职务名称可以让候选人更好的了解你. (每个月只能修改一次噢~)</text> 
				
				<text class="length-text">{{wordsLength}}/12</text> 
			</view>
		</view>
		
	</view>
</template>

<script>
	var app = getApp();
	export default {
		data() {
			return {
				position: "",
				wordsLength: 0
			}
		},
		onNavigationBarButtonTap() {
			var position = this.position;
			console.log(position.length)
			if (position.length > 12 || position.length < 2) {
				uni.showToast({
					icon: "none",
					title: "昵称长度为2-12"
				})
				return;
			}
			
			var oldPosition = this.oldPosition;
			if (oldPosition == position) {
				uni.showToast({
					icon: "none",
					title: "昵称相同"
				})
				return;
			}
			
			// this.updatePosition();
		},
		onShow() {
			this.wordsLength = this.position.length;
		},
		methods: {
			updatePosition() {
				var me = this;
				var userId = getApp().getUserInfoSession().id;
				var nickname = this.nickname;
				
				var pendingUserInfo = {
					"id": userId,
					"nickname": nickname
				};
				
				// 修改昵称
				var serverUrl = app.globalData.serverUrl;
				uni.request({
					method: "POST",
					header: {
						headerUserId: userId,
						headerUserToken: app.getUserSessionToken()
					},
					url: serverUrl + "/userInfo/modifyUserInfo?type=1",
					data: pendingUserInfo,
					success(result) {
						
						if (result.data.status == 200) {
							var userInfoUpdated = result.data.data;
							// 重置本地用户信息
							app.setUserInfoSession(userInfoUpdated);
							
							uni.navigateBack({
								delta: 1,
								animationType: "fade-out"
							})
						} else {
							uni.showToast({
								title: result.data.msg,
								icon: "none",
								duration: 3000
							});
						}
						
					}
				})
			},
			
			typingContent(e) {
				var event = e;
				this.position = e.detail.value;
				this.wordsLength = this.position.length;
			},
		}
	}
</script>

<style>
	@import url("myPosition.css");
</style>
